"""Layer A agent entrypoint. Generated by `bag recipe code agent`.

This is the VALUABLE agent AND the SOLE key-holder/signer, deployed invoke-only
on AWS Bedrock AgentCore Runtime. The keyless Layer B commerce service detects
on-chain state and invokes this agent for EVERY signing op, dispatching on
``payload["action"]``:

    quote   → read the FIXED list price → CLAMP to [min,max] → EIP-191 SIGN the
              offer (no LLM, no tools) → return the signed offer (or reject)
    fulfill → re-verify the job on-chain → LLM does the work → manifest →
              storage → submit_result (SIGN + broadcast)
    settle  → SIGN + broadcast settle (claim payment)

Envelope contract (see the two-layer deploy model, §3A):

    → {"action": "quote",
       "request": {"task_description": "...",
                   "terms": {"deliverables", "quality_standards",
                             "success_criteria"}}}
    ← the SDK NegotiationResult envelope, verbatim (see
      docs/design/erc8183-sdk-reference.md §2):
      {"request": {...}, "request_hash": "0x..",
       "response": {"accepted": true, "terms": {.., "price", "currency"},
                    "estimated_completion_seconds", "quote_expires_at"},
       "response_hash": "0x..", "negotiation_hash": "0x..",
       "provider_sig": "0x..", "chain_id": 56, "verifying_contract": "0x.."}
      // reject: response.accepted=false + response.reason_code/reason, empty sig

    → {"action": "fulfill", "job_id": "0x..", "context": {...}}
    ← {"ok": true, "tx_hash": "0x.."}     // verified, worked, submitted
      // or {"ok": false, "skip": true, "reason": "..."}   (permanent — never retry)
      // or {"ok": false, "error": "..."}                  (transient — retry)

    → {"action": "settle", "job_id": "0x.."}
    ← {"ok": true, "tx_hash": "0x.."}     // or {"ok": false, "error": "..."}

## Boundaries (do NOT cross — they are the whole point of the split)

- The agent does ALL deterministic SIGNING (quote-sign + submit + settle +
  automatic x402 LLM-credit auto-renew). ALL signing is FIXED entrypoint code
  in ``signing.py`` — NEVER an LLM-callable tool (money never in the LLM).
- The price is a FIXED list price from studio.toml (the entrypoint clamps it to
  [min,max] before signing) — the LLM never prices; it only PRODUCES the work
  text in ``fulfill``.
- Chain access for the LLM is READ-ONLY tools only (``tools.py``).
- The keyless Layer B service never signs — it only detects + triggers.
"""
from __future__ import annotations

import json
import os

from bedrock_agentcore import BedrockAgentCoreApp
from google.adk.agents import Agent
from google.adk.runners import InMemoryRunner
from google.genai import types as gtypes

from managed_model import build_model
from bnbagent_studio_core.wallet import ensure_keystore_materialized

import signing
from tools import LLM_READ_TOOLS

APP_NAME = "agent"


def _generator_tag() -> str:
    """Deliverable ``generator`` label: this seller's own name, read from
    studio.toml ``[project].name`` (minus the ``-agent`` suffix) so each
    delivered manifest is self-identifying. Best-effort — falls back to
    ``APP_NAME`` if the config can't be read."""
    try:
        from bnbagent_studio_core import config

        name = str(((config.load_studio_toml() or {}).get("project") or {}).get("name") or "")
    except Exception:  # noqa: BLE001 — a metadata label must never break fulfill
        return APP_NAME
    return name[: -len("-agent")] if name.endswith("-agent") else (name or APP_NAME)


GENERATOR = _generator_tag()

# --- Runtime secrets -----------------------------------------------------------
# Keep plaintext secrets OUT of agentcore.json. When BNBAGENT_RUNTIME_SECRET_ID is set
# (deployed runtime), pull a JSON {ENV_NAME: value} blob from AWS Secrets Manager
# into the process env BEFORE anything reads it (keystore unlock, provider key,
# build_model). No-op locally, where .env.local already populated the
# environment — `setdefault` never overrides an already-present var.
def _load_runtime_secrets() -> None:
    secret_id = os.environ.get("BNBAGENT_RUNTIME_SECRET_ID")
    if not secret_id:
        return
    import boto3

    resp = boto3.client("secretsmanager").get_secret_value(SecretId=secret_id)
    for key, value in json.loads(resp["SecretString"]).items():
        os.environ.setdefault(key, str(value))


_load_runtime_secrets()

# --- Keystore bootstrap --------------------------------------------------------
# The encrypted keystore is NEVER bundled into the AgentCore CodeZip. `bag
# deploy` injects it as the WALLET_KEYSTORE_JSON secret env var; this call (run
# once at cold start, before any signing) reconstructs the on-disk keystore so
# the unchanged disk-reading get_wallet() can unlock it with WALLET_PASSWORD.
# No-op locally where the keystore already lives on disk.
ensure_keystore_materialized()

# --- Agent + runtime ----------------------------------------------------------
# LLM credit auto-renew (Pieverse path): `build_model()` (in managed_model.py)
# returns a managed model wrapper that auto-tops up the active Pieverse key
# before each generate call when [llm.auto_renew] is enabled. That top-up is
# the ONLY automatic signing path outside signing.py — it is budget-gated and
# is NOT an LLM tool. It rides transparently for both quote and fulfill.
#
# trap: Agent.name must be a valid Python identifier — no hyphens. ADK silently
# misbehaves on names containing "-".
#
# The LLM runs ONLY in `fulfill` (the value hook). `quote` is rule-based and
# never touches the LLM (see handle_quote). The read-only chain tools are
# attached so the work can read on-chain context if it needs to — every
# registered tool rides in the prompt on every call and puts the model in
# function-calling mode, so drop them from `tools.py` if your work doesn't read
# chain. Signing / x402 / settle are NEVER tools — they are fixed code in
# signing.py, triggered by the action envelope, never callable by the LLM.
_model = build_model()  # managed model with the auto-renew hook (fulfill only)

agent = Agent(
    name="seller_agent",
    model=_model,
    instruction=(
        "You are a seller agent. You do the actual work once a job is funded. "
        "Be concrete and concise. Use the read-only chain tools when on-chain "
        "context helps."
    ),
    # LLM_READ_TOOLS = read-only chain tools (wallet, balances, ERC-8004/8183
    # queries). Edit `tools.py` to add/remove. These are READ-ONLY — the agent
    # never signs via a tool; all signing is in signing.py (fixed code).
    tools=LLM_READ_TOOLS,
)
runner = InMemoryRunner(agent=agent, app_name=APP_NAME)

app = BedrockAgentCoreApp()


# --- One-shot LLM helper ------------------------------------------------------
async def _run_llm(prompt: str, *, session_id: str) -> str:
    """Run the agent once and return the concatenated final-response text.

    ``fulfill`` returns a single response (not an SSE stream), so we collect the
    final response text rather than yielding frames. We create the session on the
    runner's own session_service (a separately-constructed InMemorySessionService
    would raise "Session not found" on run_async).
    """
    session_service = runner.session_service
    existing = await session_service.get_session(
        app_name=runner.app_name, user_id="service", session_id=session_id
    )
    if existing is None:
        await session_service.create_session(
            app_name=runner.app_name, user_id="service", session_id=session_id
        )

    user_msg = gtypes.Content(role="user", parts=[gtypes.Part(text=prompt)])
    parts: list[str] = []
    async for event in runner.run_async(
        user_id="service", session_id=session_id, new_message=user_msg
    ):
        if event.is_final_response() and event.content:
            for p in event.content.parts:
                if p.text:
                    parts.append(p.text)
    return "\n".join(parts).strip()


def _parse_job_id(raw) -> int:
    """Normalise an envelope ``job_id`` to the SDK's integer id.

    ERC-8183 job ids are sequential integers (``job_counter``). The envelope
    may carry it as ``"0x.."``, a decimal string, or an int — accept all.
    """
    if isinstance(raw, int):
        return raw
    s = str(raw).strip()
    return int(s, 16) if s.lower().startswith("0x") else int(s)


# --- Action handlers ----------------------------------------------------------
async def handle_quote(request: dict) -> dict:
    """Rule-based quote → the SDK ``NegotiationResult`` envelope (returned verbatim).

    No LLM, no tools — pricing is deterministic policy; the structured, signed,
    expiring envelope is entirely the SDK's job (``signing.sign_quote`` →
    ``NegotiationHandler``). The list price comes from ``[payments.erc8183].price``
    and is clamped to ``[min_price, max_price]`` before signing, so a misconfigured
    price can never sign out of bounds. Change what you charge by editing ``price``
    in studio.toml; for per-task pricing, compute the price from ``request`` before
    clamping. The Service relays this envelope to the buyer verbatim.
    """
    clamped = signing.clamp_price(signing.list_price())
    return signing.sign_quote(request, clamped)


async def handle_fulfill(job_id: int, context: dict) -> dict:
    """Re-verify the job on-chain, do the work, then SIGN + submit on-chain.

    Before doing ANY work we verify the funded job carries the exact quote THIS
    agent signed (``signing.verify_signed_job`` → ecrecover + budget≥price). A
    permanent failure (not our signature, tampered terms, underfunded, no signed
    quote, expired) returns ``{ok:false, skip:true, reason}`` so the Service skips
    it forever; a transient failure returns ``{ok:false, error}`` to retry. Only a
    verified job runs the LLM + ``signing.submit_result`` (which re-runs the SDK's
    ``verify_job`` — defense in depth). The LLM body below is the DEVELOPER HOOK:
    replace it with your real work; the returned text becomes the on-chain manifest.
    """
    # --- VERIFY before working: is this the exact deal we signed? ---------------
    ok, reason, permanent = signing.verify_signed_job(job_id)
    if not ok:
        if permanent:
            return {"ok": False, "skip": True, "reason": reason}
        return {"ok": False, "error": reason}

    # ----------------------------------------------------------------------
    # DEVELOPER HOOK — implement your actual task fulfilment here.
    # The block below is a generic LLM passthrough so the recipe runs E2E
    # out of the box. Specialise it for your seller.
    # ----------------------------------------------------------------------
    # The task + terms the buyer ANCHORED ON-CHAIN (and we signed in negotiation)
    # are the authoritative spec — read them here, NOT from Service-relayed
    # context (the keyless Service forwards none). Fall back to context only for
    # legacy/unstructured descriptions.
    spec = signing.job_spec(job_id)
    if spec is not None:
        task = json.dumps({"task": spec.task, "terms": spec.terms}, ensure_ascii=False)
    else:
        task = (context or {}).get("task_description") or json.dumps(context or {})

    prompt = (
        "You accepted and were paid for the following job. Produce the "
        "deliverable now. Be complete and self-contained.\n\n"
        f"JOB CONTEXT:\n{task}"
    )
    work = await _run_llm(prompt, session_id=str(job_id))

    metadata = {
        "job_id": job_id,
        "generator": GENERATOR,
        # Public studio attribution — same key + URL as the Service's /status
        # built_with (and aligned with the SDK's built_with convention).
        "built_with": "https://github.com/bnb-chain/bnbagent-studio",
    }
    # signing.submit_result RAISES on a failed submit (studio-core turns the
    # SDK's {success: False} envelope into SdkCallFailedError), so reaching the
    # return below means submit_tx is a real on-chain tx hash. The entrypoint
    # maps the raise to an {ok: false, error} ack — transient, so the Service
    # retries. Never ack ok without a landed tx.
    res = signing.submit_result(
        job_id,
        response_content=work,
        metadata=metadata,
    )
    # Hand the Service the on-chain deliverable URL (ipfs://CID) so it resolves +
    # caches the CANONICAL manifest from storage — keeping the served /response
    # byte-identical to what's on-chain (re-hashable to the submitted bytes32).
    return {"ok": True, "tx_hash": res.submit_tx, "deliverable_url": res.deliverable_url}


async def handle_settle(job_id: int) -> dict:
    """SIGN + broadcast settle (claim payment) for ``job_id``."""
    tx_hash = signing.settle(job_id)
    return {"ok": True, "tx_hash": tx_hash}


# --- AgentCore entrypoint -----------------------------------------------------
@app.entrypoint
async def invoke(payload, context=None):
    """AgentCore /invocations entrypoint — dispatch on ``payload["action"]``.

    Returns a JSON-serializable envelope (dict). Invoke-only: the keyless
    Layer B service is the sole caller.
    """
    action = (payload or {}).get("action")

    if action == "quote":
        return await handle_quote(payload.get("request", {}) or {})

    if action == "fulfill":
        try:
            jid = _parse_job_id(payload.get("job_id", ""))
        except (TypeError, ValueError):
            return {"ok": False, "error": f"invalid job_id: {payload.get('job_id')!r}"}
        try:
            return await handle_fulfill(jid, payload.get("context", {}) or {})
        except Exception as e:  # noqa: BLE001 — surface on-chain/work errors as an ack
            return {"ok": False, "error": str(e)}

    if action == "settle":
        try:
            jid = _parse_job_id(payload.get("job_id", ""))
        except (TypeError, ValueError):
            return {"ok": False, "error": f"invalid job_id: {payload.get('job_id')!r}"}
        try:
            return await handle_settle(jid)
        except Exception as e:  # noqa: BLE001 — surface settle errors as an ack
            return {"ok": False, "error": str(e)}

    return {
        "error": f"unknown action: {action!r}",
        "supported": ["quote", "fulfill", "settle"],
    }


if __name__ == "__main__":
    app.run(port=int(os.environ.get("AGENT_PORT", "8080")))
